"""Standalone offline replay of recorded sandbox evidence; no wallet or network controls."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
import sys
OUT=ROOT.parent.parent/('results/near-chambers-20261105/swarm' if '--chambers-regression' in sys.argv else 'results/near-swarm-20261104')
def main():
    summary=json.loads((OUT/'SUMMARY.json').read_text());privacy=json.loads((OUT/'PRIVACY.json').read_text())
    if summary['failed'] or not summary['passed']:raise RuntimeError('Cannot render failed evidence')
    payload=json.dumps({'snapshots':summary['snapshots'],'passed':summary['passed'],'privacy':privacy},ensure_ascii=True).replace('<','\\u003c')
    html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:;"><title>MultiHopper · Swarm Treasury Demo</title>
<style>*{box-sizing:border-box}body{margin:0;background:#101820;color:#e9f0f1;font:16px system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:45px 24px}h1{font-size:clamp(32px,5vw,52px);letter-spacing:-2px;margin:18px 0}p{line-height:1.6;color:#b7c5cc}small{color:#a7bdc6}.pill{display:inline-block;border:1px solid #426d60;border-radius:30px;padding:7px 12px;color:#a3e7cb;font-size:12px;letter-spacing:1px}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:25px 0}button,select{background:#d0f2e3;color:#15261f;border:0;padding:12px 16px;border-radius:8px;font:inherit}button:disabled{opacity:.4}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card,.panel{background:#19262f;border:1px solid #34444e;border-radius:16px;padding:22px}.card h2{margin:0 0 10px}.state{font-size:13px;color:#a3e7cb}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.metric b{display:block;font-size:28px;color:#edf8f3}.metric span{font-size:11px;text-transform:uppercase;color:#9fb3bd}.slot{border-top:1px solid #34444e;padding:14px 0}.slot strong{font-size:14px}.slot p{font-size:13px;margin:7px 0}.address{font:11px monospace;overflow-wrap:anywhere;color:#9eb7c3}.panel{margin-top:20px}.privacy{border-color:#836c45}.privacy strong{color:#f7ce8e}#event{min-height:34px;font-size:22px}footer{font-size:12px;color:#90a5b0;margin-top:24px}@media(max-width:760px){.grid{grid-template-columns:1fr}.metrics{gap:4px}.metric b{font-size:23px}}</style>
<main><span class="pill">REAL LOCAL NEAR SANDBOX · SYNTHETIC ASSETS ONLY</span><h1>Agents can work.<br>Customer funds stay separate.</h1><p>MultiHopper gives each job fixed agent budgets, separate custody and a path to recover unused funds. This page replays verified transactions; it cannot sign, fund or submit anything.</p>
<div class="toolbar"><label for="phase">Recorded event</label><select id="phase"></select><button id="next">Next event →</button><button id="reset">Replay from start</button></div><h2 id="event" aria-live="polite"></h2><div class="grid" id="jobs"></div>
<div class="panel"><h2>What MultiHopper contributes</h2><p>Each agent allocation has its own custody account and key. On-chain policies cap spending; the provider signs only the bound payment. A failed job revokes future grants and reconciles existing transactions before returning remaining principal. One customer never pays another customer's shortfall.</p><small>Fixed allocations, not a shared liquidity pool. Agents here are scripted test actors; work quality, bidding and dispute arbitration are not automated by this demo.</small></div>
<div class="panel privacy"><h2>Privacy: measured, not assumed</h2><p id="privacy"></p><small>No job title, prompt or invoice text is added to payment memos. Public token-account relationships still reveal the path. The observer received public history only; this is a deterministic graph test, not a human/LLM cold-start timing benchmark.</small></div>
<footer id="evidence"></footer></main><script>
const evidence=PAYLOAD;const phase=document.getElementById('phase');const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
evidence.snapshots.forEach((s,i)=>{const o=document.createElement('option');o.value=i;o.textContent=(i+1)+'. '+s.label;phase.appendChild(o);});
function render(){const i=Number(phase.value);const frame=evidence.snapshots[i];document.getElementById('event').textContent=frame.label;document.getElementById('next').disabled=i===evidence.snapshots.length-1;
document.getElementById('jobs').innerHTML=frame.jobs.map(j=>`<article class="card"><h2>${escape(j.owner.split('.')[0])}'s job</h2><div class="state">${escape(j.status)}</div><p>${escape(j.title)}</p><div class="metrics">${[['Funded',j.funded],['Spent',j.spent],['Remaining',j.principal],['Returned',j.refunded]].map(([k,v])=>`<div class="metric"><b>${escape(v)}</b><span>${k}</span></div>`).join('')}</div>${j.slots.map(s=>`<div class="slot"><strong>${escape(s.role)} agent · cap ${escape(s.allocation)}</strong><p>Maximum ${escape(s.perPayment)} per payment · ${escape(s.spent)} spent · ${escape(s.refunded)} returned</p><div class="address">Separate custody: ${escape(s.address)}</div></div>`).join('')}</article>`).join('');}
phase.addEventListener('change',render);document.getElementById('next').addEventListener('click',()=>{phase.value=Number(phase.value)+1;render();});document.getElementById('reset').addEventListener('click',()=>{phase.value=0;render();});
document.getElementById('privacy').innerHTML='<strong>'+evidence.privacy.correctUnique+' / '+evidence.privacy.payments+' payments traced to their customer source.</strong> The privacy gate failed; this demo establishes custody and payment controls, not unlinkability.';
document.getElementById('evidence').textContent=evidence.passed+' Swarm scenarios passed on a disposable local NEAR chain. Local software provider, not production HSM/MPC. Unknown outcomes block recovery. Production untouched.';render();
</script></html>'''.replace('PAYLOAD',payload)
    (OUT/'demo.html').write_text(html)
if __name__=='__main__':main()
